          <path d="m11 18-6-6 6-6"></path>
        </svg>
      </button>
    </header>

    <main>
      <section class="amount-card" aria-labelledby="amount-label">
        <p class="amount-label" id="amount-label">المبلغ المستحق</p>
        <p class="amount" aria-label="1,234.50 درهم إماراتي">
          1,234.50 <span class="currency">د.إ</span>
        </p>
        <p class="order-count">
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <path d="M4 7h16l-1 13H5L4 7Z"></path>
            <path d="M9 9V6a3 3 0 0 1 6 0v3"></path>
          </svg>
          يحتوي طلبك على 3 عناصر
        </p>
      </section>

      <section class="details-card" aria-label="تفاصيل الدفع">
        <div class="detail-row">
          <p class="detail-label">تاريخ الاستحقاق</p>
          <div class="detail-value calendar-value">
            <span>3 نوفمبر 2026</span>
            <span class="hijri">20 ربيع الآخر 1448 هـ</span>
          </div>
        </div>

        <div class="detail-row">
          <p class="detail-label">طريقة الدفع</p>
          <p class="detail-value">بطاقة بنكية</p>
        </div>
      </section>

      <section class="field-section" aria-labelledby="phone-title">
        <h2 class="field-title" id="phone-title">
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <rect x="6" y="2" width="12" height="20" rx="2"></rect>
            <path d="M9 6h6"></path>
            <path d="M10 18h4"></path>
          </svg>
          إرسال الإيصال
        </h2>
        <p class="field-description">أدخل رقم الهاتف لإرسال الإيصال عبر رسالة نصية.</p>

