          <label for="phone" hidden>رقم الهاتف</label>
          <div class="phone-wrap">
            <span class="country-code" aria-hidden="true">+971</span>
            <input
              class="phone-input"
              id="phone"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              dir="ltr"
              placeholder="050 123 4567"
              aria-describedby="phoneError"
            >
          </div>
          <p class="field-error" id="phoneError" role="alert"></p>

          <button class="pay-button" id="payButton" type="submit">ادفع الآن</button>
          <p class="status-message" id="statusMessage" role="status" aria-live="polite"></p>
        </form>

