  <script>
    const form = document.getElementById("paymentForm");
    const phoneInput = document.getElementById("phone");
    const phoneError = document.getElementById("phoneError");
    const statusMessage = document.getElementById("statusMessage");
    const payButton = document.getElementById("payButton");

    function normalizeDigits(value) {
      return value.replace(/[٠-٩]/g, digit => String(digit.charCodeAt(0) - 0x0660));
    }

    function validatePhone(value) {
      const digits = normalizeDigits(value).replace(/\D/g, "");
      if (/^0/.test(digits)) return digits.length === 10 && digits.startsWith("05");
      if (/^971/.test(digits)) return digits.length === 13 && digits.startsWith("9715");
      if (/^\+971/.test(value.replace(/\s/g, ""))) {
        const withoutPrefix = digits.replace(/^971/, "");
        return withoutPrefix.length === 9 && withoutPrefix.startsWith("5");
      }
      return false;
    }

    phoneInput.addEventListener("input", () => {
      phoneError.textContent = "";
      statusMessage.textContent = "";
    });

    form.addEventListener("submit", event => {
      event.preventDefault();

      if (!validatePhone(phoneInput.value)) {
        phoneError.textContent = "أدخل رقم هاتف إماراتي صحيح، مثل 050 123 4567.";
        phoneInput.setAttribute("aria-invalid", "true");
        phoneInput.focus();
        return;
      }

      phoneInput.removeAttribute("aria-invalid");
      payButton.disabled = true;
      payButton.textContent = "جارٍ تنفيذ الدفع…";

      window.setTimeout(() => {
        payButton.disabled = false;
        payButton.textContent = "ادفع الآن";
        statusMessage.textContent = "تم تسجيل طلب الدفع بنجاح.";
      }, 900);
    });
  </script>
